def mostrar_dashboard(ranking: pd.DataFrame, detalle_general: pd.DataFrame, resultados: pd.DataFrame):
    mostrar_campeon_final(ranking, resultados)
    mostrar_estado_torneo(ranking, resultados)
    mostrar_metricas(ranking, detalle_general, resultados)

    st.markdown("## 🏆 Podio actual")

    if len(ranking) >= 3:
        col1, col2, col3 = st.columns(3)

        podio = [
            (col1, "🥈", "Segundo Lugar", ranking.iloc[1]["Jugador"], int(ranking.iloc[1]["Puntos"]), "podio-card"),
            (col2, "🥇", "Primer Lugar", ranking.iloc[0]["Jugador"], int(ranking.iloc[0]["Puntos"]), "podio-card podio-card-oro"),
            (col3, "🥉", "Tercer Lugar", ranking.iloc[2]["Jugador"], int(ranking.iloc[2]["Puntos"]), "podio-card"),
        ]

        for columna, medalla, titulo, jugador, puntos, clase in podio:
            with columna:
                st.markdown(
                    f"""
                    <div class="{clase}">
                        <div class="podio-medalla">{medalla}</div>
                        <div class="podio-titulo">{titulo}</div>
                        <div class="podio-jugador">{jugador}</div>
                        <div class="podio-puntos">{puntos} pts</div>
                    </div>
                    """,
                    unsafe_allow_html=True,
                )

        st.divider()
    else:
        st.info("Aún no hay suficientes jugadores para mostrar el podio.")

    st.markdown("## 🏆 Tabla de posiciones general")

    ranking_visual = agregar_medallas(ranking)

    def resaltar_filas(fila):
        posicion = fila["Posición"]
        if posicion == 1:
            return ["background-color: #fff3cd; font-weight: bold"] * len(fila)
        elif posicion == 2:
            return ["background-color: #f1f3f5; font-weight: bold"] * len(fila)
        elif posicion == 3:
            return ["background-color: #fce5cd; font-weight: bold"] * len(fila)
        return [""] * len(fila)

    st.dataframe(
        ranking_visual.style.apply(resaltar_filas, axis=1),
        use_container_width=True,
        hide_index=True,
    )

    guardar_ranking_output(ranking)

    st.markdown("## 📊 Carrera por el liderato")

    ranking_grafico = ranking.sort_values(
        by=["Puntos", "Marcadores exactos", "Jugador"],
        ascending=[False, False, True],
    ).reset_index(drop=True)

    puntos_maximos = int(ranking_grafico["Puntos"].max()) if not ranking_grafico.empty else 0

    barras_html = ""

    for _, fila in ranking_grafico.iterrows():
        jugador = fila["Jugador"]
        puntos = int(fila["Puntos"])
        porcentaje = 0 if puntos_maximos == 0 else int((puntos / puntos_maximos) * 100)

        barras_html += f"""
        <div class="barra-ranking">
            <div class="barra-label">
                <span>{jugador}</span>
                <span>{puntos} pts</span>
            </div>
            <div class="barra-fondo">
                <div class="barra-progreso" style="width: {porcentaje}%;"></div>
            </div>
        </div>
        """

    st.markdown(
        f"""
        <div class="grafico-card">
            <div class="grafico-subtitulo">
                Visualiza la diferencia de puntos entre participantes.
            </div>
            {barras_html}
        </div>
        """,
        unsafe_allow_html=True,
    )

    excel = generar_excel_ranking(ranking)

    st.download_button(
        label="📥 Exportar ranking a Excel",
        data=excel,
        file_name="ranking_toto_gol.xlsx",
        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    )

    st.markdown("## 🎙️ Crónica deportiva")
    comentario = generar_comentario_periodista(ranking)
    st.markdown(
        f"""
        <div class='card-periodista'>
            <div class='cronica-etiqueta'>🔥 Análisis automático</div>
            <div class='cronica-titulo'>La jornada en el TotoGolFamiliar</div>
            <div class='cronica-texto'>{comentario}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    st.markdown("## 📲 Centro de difusión")
    resumen = generar_resumen_whatsapp(ranking)

    resumen_con_url = (
        f"{resumen}\n\n"
        f"🌐 Ver clasificación completa:\n{URL_DASHBOARD}"
    )

    mensaje_whatsapp = quote(resumen_con_url)
    whatsapp_url = f"https://wa.me/?text={mensaje_whatsapp}"

    st.markdown(
        f"""
        <div class='whatsapp-card'>
            <div class='whatsapp-etiqueta'>📲 Listo para compartir</div>
            <div class='whatsapp-titulo'>Mensaje para el grupo familiar</div>
            <div class='whatsapp-subtitulo'>
                Copia o comparte automáticamente la clasificación actual del TotoGolFamiliar.
            </div>
            <div class='whatsapp-box'>{resumen_con_url}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    st.link_button(
        "📲 Compartir ranking por WhatsApp",
        whatsapp_url,
        use_container_width=True,
    )


def mostrar_detalle_jugador(ranking: pd.DataFrame, detalle_general: pd.DataFrame):
    st.markdown("## 👤 Detalle de Jugador")

    if detalle_general.empty:
        st.warning("⚠️ Todavía no hay partidos procesados para mostrar detalles.")
        return

    jugadores = sorted(detalle_general["Jugador"].dropna().unique())

    jugador_seleccionado = st.selectbox(
        "Selecciona un jugador",
        jugadores,
    )

    detalle = detalle_general[detalle_general["Jugador"] == jugador_seleccionado].copy()

    if detalle.empty:
        st.warning("⚠️ Este jugador aún no tiene partidos con resultado oficial.")
        return

    detalle = detalle.sort_values(by="id_partido")

    columnas_mostrar = [
        "id_partido",
        "grupo",
        "local",
        "visitante",
        "goles_local",
        "goles_visitante",
        "goles_local_real",
        "goles_visitante_real",
        "Puntos",
    ]

    columnas_disponibles = [col for col in columnas_mostrar if col in detalle.columns]

    total = int(detalle["Puntos"].sum())
    exactos = int(detalle["Marcador exacto"].sum())
    correctos = int(detalle["Resultado correcto"].sum())
    incorrectos = int(detalle["Predicción incorrecta"].sum())

    col1, col2, col3, col4 = st.columns(4)
    col1.metric("Total acumulado", total)
    col2.metric("Marcadores exactos", exactos)
    col3.metric("Resultados correctos", correctos)
    col4.metric("Incorrectas", incorrectos)

    st.dataframe(
        detalle[columnas_disponibles],
        use_container_width=True,
        hide_index=True,
    )


def preparar_datos() -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    partidos = leer_excel(PARTIDOS_FILE, COLUMNAS_PARTIDOS, "data/partidos.xlsx")
    resultados = leer_excel(RESULTADOS_FILE, COLUMNAS_RESULTADOS, "data/resultados.xlsx")

    partidos = limpiar_id_partido(partidos)
    resultados = limpiar_id_partido(resultados)

    resultados = convertir_goles_a_numero(
        resultados,
        ["goles_local_real", "goles_visitante_real"],
    )

    resultados = resultados.dropna(
        subset=["goles_local_real", "goles_visitante_real"]
    )

    ranking, detalle_general = calcular_ranking(partidos, resultados)

    return partidos, resultados, ranking, detalle_general


